-- FINANCE DATABASE SCHEMA AND DATA (OPTIMIZED VERSION)
-- Generated on: 2026-05-02 12:46:31
-- ============================================

-- Drop and create database
DROP DATABASE IF EXISTS finance_db;
CREATE DATABASE finance_db;
USE finance_db;

-- Disable foreign key checks for faster loading
SET FOREIGN_KEY_CHECKS = 0;
SET UNIQUE_CHECKS = 0;
SET AUTOCOMMIT = 0;

-- ============================================
-- TABLE 1: LOAN DETAILS (46 columns)
-- ============================================


CREATE TABLE loan_details (
    loan_id VARCHAR(20) PRIMARY KEY,
    customer_id VARCHAR(20) NOT NULL,
    application_date DATE,
    approval_date DATE,
    disbursement_date DATE,
    loan_amount DECIMAL(12,2),
    interest_rate DECIMAL(5,2),
    loan_tenure_months INT,
    emi_amount DECIMAL(10,2),
    customer_name VARCHAR(100),
    customer_age INT,
    customer_gender VARCHAR(10),
    customer_email VARCHAR(100),
    customer_phone VARCHAR(20),
    address_line1 VARCHAR(200),
    address_line2 VARCHAR(200),
    city VARCHAR(50),
    state VARCHAR(50),
    pincode VARCHAR(10),
    country VARCHAR(50),
    employment_type VARCHAR(50),
    annual_income DECIMAL(12,2),
    company_name VARCHAR(100),
    years_in_current_job DECIMAL(5,2),
    credit_score INT,
    existing_loans_count INT,
    total_existing_loan_amount DECIMAL(12,2),
    default_history TINYINT,
    loan_purpose VARCHAR(50),
    loan_status VARCHAR(20),
    closure_date DATE,
    next_emi_date DATE,
    collateral_required TINYINT,
    collateral_type VARCHAR(50),
    collateral_value DECIMAL(12,2),
    processing_fee_percent DECIMAL(5,2),
    processing_fee_amount DECIMAL(10,2),
    gst_on_processing_fee DECIMAL(10,2),
    bank_name VARCHAR(50),
    account_number VARCHAR(20),
    ifsc_code VARCHAR(20),
    is_npa TINYINT,
    emi_bounce_count INT,
    has_insurance TINYINT,
    insurance_provider VARCHAR(50),
    created_at DATETIME,
    updated_at DATETIME,
    INDEX idx_customer_id (customer_id),
    INDEX idx_loan_status (loan_status),
    INDEX idx_disbursement_date (disbursement_date),
    INDEX idx_credit_score (credit_score)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- ============================================
-- TABLE 2: EMI PAID INFORMATION (18 columns)
-- ============================================


CREATE TABLE emi_information (
    emi_id VARCHAR(20) PRIMARY KEY,
    loan_id VARCHAR(20) NOT NULL,
    emi_number INT,
    emi_due_date DATE,
    emi_paid_date DATE,
    emi_status VARCHAR(20),
    principal_amount DECIMAL(10,2),
    interest_amount DECIMAL(10,2),
    late_fee DECIMAL(10,2),
    total_amount_paid DECIMAL(10,2),
    payment_method VARCHAR(30),
    transaction_id VARCHAR(50),
    bank_reference_number VARCHAR(50),
    outstanding_principal_after_emi DECIMAL(12,2),
    is_emi_bounced TINYINT,
    bounce_reason VARCHAR(100),
    penalty_charged DECIMAL(10,2),
    created_at DATETIME,
    FOREIGN KEY (loan_id) REFERENCES loan_details(loan_id),
    INDEX idx_loan_id (loan_id),
    INDEX idx_emi_due_date (emi_due_date),
    INDEX idx_emi_status (emi_status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;



