-- ============================================
-- VERIFICATION QUERIES
-- ============================================

-- Check record counts
SELECT 'loan_details' AS table_name, COUNT(*) AS total_records FROM loan_details
UNION ALL
SELECT 'emi_information', COUNT(*) FROM emi_information;

-- Sample data from loan_details
SELECT * FROM loan_details LIMIT 5;

-- Sample data from emi_information
SELECT * FROM emi_information LIMIT 5;

-- Loan status distribution
SELECT loan_status, COUNT(*) as count, ROUND(COUNT(*)*100/(SELECT COUNT(*) FROM loan_details),2) as percentage
FROM loan_details GROUP BY loan_status;

-- EMI status distribution
SELECT emi_status, COUNT(*) as count, ROUND(COUNT(*)*100/(SELECT COUNT(*) FROM emi_information),2) as percentage
FROM emi_information GROUP BY emi_status;

-- Top 10 customers by loan amount
SELECT customer_id, customer_name, loan_amount, loan_status
FROM loan_details ORDER BY loan_amount DESC LIMIT 10;

-- EMI collection efficiency
SELECT 
    COUNT(CASE WHEN emi_status = 'Paid' THEN 1 END) as total_paid_emis,
    COUNT(CASE WHEN emi_status = 'Overdue' THEN 1 END) as total_overdue_emis,
    COUNT(CASE WHEN emi_status = 'Pending' THEN 1 END) as total_pending_emis,
    ROUND(COUNT(CASE WHEN emi_status = 'Paid' THEN 1 END)*100.0/COUNT(*),2) as collection_efficiency
FROM emi_information;

